package com.acely.ai;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Value; import org.springframework.http.MediaType; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient;
@Service public class GeminiService {
 private final RestClient client=RestClient.create(); private final ObjectMapper mapper=new ObjectMapper(); @Value("${gemini.api-key}") String key; @Value("${gemini.model}") String model;
 public JsonNode generate(String instruction, String material) { if(key==null || key.isBlank()) throw new IllegalStateException("AI generation is not configured. Add GEMINI_API_KEY to backend/.env or your environment."); String prompt=instruction+"\n\nStudy material (use only this):\n"+material.substring(0, Math.min(material.length(), 60000)); try { var body=mapper.createObjectNode(); var parts=body.putArray("contents").addObject().putArray("parts"); parts.addObject().put("text",prompt); String raw=client.post().uri("https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent?key={key}",model,key).contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(String.class); JsonNode response=mapper.readTree(raw); String text=response.path("candidates").path(0).path("content").path("parts").path(0).path("text").asText(); return parseJson(text); } catch(Exception e) { throw new IllegalStateException("Acely could not generate learning resources. Please try again."); } }
 private JsonNode parseJson(String text) throws Exception { String cleaned=text.replaceAll("(?s)^\\s*```(?:json)?\\s*|\\s*```\\s*$", "").trim(); JsonNode node=mapper.readTree(cleaned); if(node==null || node.isMissingNode()) throw new IllegalArgumentException("The AI returned an invalid response."); return node; }
}
